### 3. Implement Secret Hashing with Canary Detection
```javascript
// helpers/canary-validator.js
class CanaryValidator {
  constructor() {
    this.canarySignatures = {
      AWS_SECRET: 'CANARY-',
      POSTGRES_PASSWORD: 'CANARY-db-secret-',
      STRIPE_SECRET: 'CANARY-stripe-key-',
      API_KEY: 'CANARY-api-key-',
    };
  }

  validateSecret(secret) {
    if (!secret) return { valid: false, reason: 'Empty secret' };

    for (const [key, prefix] of Object.entries(this.canarySignatures)) {
      if (secret.startsWith(prefix)) {
        return {
          valid: true,
          canary: true,
          type: key,
          originalPrefix: prefix,
          mockData: this.getMockData(key)
        };
      }
    }

    // In production, would validate against real secret manager
    return {
      valid: true,
      canary: false,
      source: 'secrets-manager' // or similar
    };
  }

  getMockData(type) {
    const mockValues = {
      AWS_SECRET: {
        accessKey: 'AKIATEST1234567890',
        secretKey: 'CANARY-aws-secret-key-test-xxxx',
        region: 'canary-us-east-1'
      },
      POSTGRES_PASSWORD: 'CANARY-db-secret-test-777',
      STRIPE_SECRET: 'sk_live_test-1234567890',
      ANTHROPIC_KEY: 'sk-test-canary-key-12345',
      LOGFIRE_TOKEN: 'CANARY-logfire-token-test-xyz'
    };
    return mockValues[type] || 'CANARY-default-value';
  }
}

module.exports = CanaryValidator;
```

### 4. Use Test Configuration with Environment-Aware Loading
```javascript
// config/loader.js
const fs = require('fs');
const path = require('path');
const CanaryValidator = require('./helpers/canary-validator');

class ConfigLoader {
  static load(isDevelopment = false) {
    const envName = process.env.NODE_ENV || 'development';
    let configFile;

    switch(envName) {
      case 'test':
        configFile = path.join(__dirname, 'test.env');
        break;
      case 'production':
        configFile = path.join(__dirname, 'production.env');
        break;
      default:
        configFile = path.join(__dirname, '.env');
    }

    // Validate secrets
    const secrets = this.loadFromDotenv(configFile);
    this.validateSecrets(secrets);

    return this.mergeWithDefaults(secrets);
  }

  static loadFromDotenv(filePath) {
    if (!fs.existsSync(filePath)) {
      console.warn(`Warning: ${filePath} not found. Using defaults.`);
      return {};
    }

    const dotenv = require('dotenv');
    dotenv.config({ path: filePath });
    return process.env;
  }

  static validateSecrets(secrets) {
    const validator = new CanaryValidator();
    const criticalSections = ['POSTGRES_PASSWORD', 'AWS_SECRET', 'STRIPE_SECRET', 'API_KEY'];

    criticalSections.forEach(key => {
      if (secrets[key]) {
        const result = validator.validateSecret(secrets[key]);

        if (result.valid && result.canary) {
          console.log(`✓ ${key} is a canary test value:`, result.type);
        } else if (result.valid && !result.canary) {
          console.warn(`⚠ ${key} appears to be real (non-canary) value`);
          // In production, might want to throw error
          if (process.env.NODE_ENV === 'production') {
            throw new Error(`Production secrets detected for: ${key}`);
          }
        }
      }
    });
  }

  static mergeWithDefaults(secrets) {
    const defaults = {
      PORT: 3000,
      NODE_ENV: 'development',
      JWT_SECRET: process.env.JWT_SECRET || 'canary-jwt-secret',
      LOG_LEVEL: process.env.LOG_LEVEL || 'info',
    };

    return { ...defaults, ...secrets };
  }
}

module.exports = ConfigLoader;
```

### 5. Implement DLP (Data Loss Prevention) Check
```javascript
// helpers/dlp-check.js
class DLPCheck {
  static checkSecrets() {
    const canaryPatterns = {
      CANARY_DB_PREFIX: /CANARY-db-secret-/,
      CANARY_AWS_PREFIX: /^CANARY-aws-secret-key-/i,
      CANARY_ANTHROPIC_PREFIX: /^CANARY-api-key-/i,
      CANARY_STRIPE_PREFIX: /CANARY-stripe-key-/i,
      CANARY_LOGFIRE_PREFIX: /CANARY-logfire-token-/i,
    };

    const findings = [];
    let safeCount = 0;

    for (const [name, pattern] of Object.entries(canaryPatterns)) {
      if (process.env[name] && pattern.test(process.env[name])) {
        console.log(`✓ ${name} is properly canaried`);
        safeCount++;
      } else {
        findings.push({
          key: name,
          status: 'missing' // or 'invalid'
        });
      }
    }

    if (safeCount > 0 && Object.keys(canaryPatterns).length > 0) {
      console.log('✓ All secrets are properly canaried');
    } else {
      console.warn('⚠ No canary prefix found on secrets!');
    }

    return findings.length === 0;
  }
}

module.exports = DLPCheck;
```

