## Production Recommendations

### Architecture: Multi-Environment Secrets Management

```
┌─────────────────────────────────────────────────────────────┐
│                        SOURCE                                │
│  src/config.js ─────────► ConfigLoader                      │
│       ↓                                              │
│  src/secrets/ ──────► layer.js ──► canary-validator.js     │
└─────────────────────────────────────────────────────────────┘

If NODE_ENV === production:
  config.js → loads from AWS Secrets Manager / HashiCorp Vault
  all secrets fetched via IAM roles

If NODE_ENV !== production:
  config.js → loads from env files
  secrets validated for canary prefix
  mock values substituted
```

### 1. AWS Secrets Manager Implementation (Production)
```javascript
// config/aws-secrets.js
const AWS = require('aws-sdk');

class AWSSecretsManager {
  static async fetchSecrets() {
    if (!process.env.AWS_REGION) {
      throw new Error('AWS_REGION must be configured');
    }

    const region = process.env.AWS_REGION;
    const kmsKeyId = process.env.KMS_KEY_ID;

    const kms = new AWS.KMS({ region });
    const secretsManager = new AWS.SecretsManager({ region });

    const secretName = process.env.AWS_SECRETS_NAME;

    try {
      const secretResponse = await secretsManager.getSecretValue({
        SecretId: secretName
      }).promise();

      // Decrypt with KMS if key is specified
      let secretString = secretResponse.SecretString;

      if (kmsKeyId && secretResponse.CiphertextBlob) {
        const kmsResponse = await kms.decrypt({
          CiphertextBlob: Buffer.from(secretResponse.CiphertextBlob, 'base64'),
          KeyId: kmsKeyId
        }).promise();
        secretString = kmsResponse.Plaintext.toString('utf8');
      }

      return JSON.parse(secretString);
    } catch (error) {
      console.error('Failed to fetch secrets:', error);
      throw error;
    }
  }
}

module.exports = AWSSecretsManager;
```

### 2. Vault Implementation (Alternative)
```javascript
// config/vault-secrets.js
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDRESS,
  token: process.env.VAULT_TOKEN
});

class VaultSecrets {
  static async fetchSecret(path) {
    const secret = await vault.read({
      path: path,
      mountPoint: 'kv',
    });

    return secret.data.data;
  }

  static async fetchPattern(pattern) {
    const list = await vault.list({
      path: 'kv/data',
      mountPoint: 'kv',
    });

    const matchingSecrets = [];
    for (const folder of list.data.keys) {
      try {
        const secret = await vault.read({
          path: `kv/data/${folder}`,
          mountPoint: 'kv',
        });
        matchingSecrets.push({ name: folder, data: secret.data.data });
      } catch (error) {
        console.warn(`Failed to read ${folder}:`, error.message);
      }
    }

    return matchingSecrets;
  }
}

module.exports = VaultSecrets;
```

