# Security Review of app.js
**Date:** June 6, 2024

## Executive Summary
This review identified **14 high-severity vulnerabilities** in the application. The application is severely vulnerable to multiple attack vectors due to lack of essential security controls.

---

## Critical Vulnerabilities

### 1. ❌ Missing Rate Limiting - **CRITICAL**

**OWASP Category:** A07:2021 - Identification and Authentication Failures

**Risk:** Attackers can brute force endpoints, DOS attacks, abuse resources.

**Current Code:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Vulnerability:** No rate limiting protection on any route.

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

// Apply rate limiting globally
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});

app.use(limiter);

// More strict for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5 // limit to 5 requests per 15 minutes per IP
});

app.post('/login', authLimiter, loginHandler);
```

---

### 2. ❌ Missing CORS Configuration - **HIGH**

**OWASP Category:** A05:2021 - Security Misconfiguration

**Risk:** Allow sites to make unauthorized cross-origin requests (CSRF, data theft).

**Current Code:**
```javascript
const express = require('express');
const app = express();
```

**Vulnerability:** Default CORS policy allows all origins.

**Recommendation:**
```javascript
const cors = require('cors');

app.use(cors({
  origin: 'https://yourdomain.com', // Specify allowed origins
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // Cache preflight response for 24 hours
}));
```

---

### 3. ❌ Missing Input Validation - **HIGH**

**OWASP Category:** A03:2021 - Injection

**Risk:** Injection attacks via query parameters and request data.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Vulnerability:** No validation of query parameters if user input is added.

**Recommendation:**
```javascript
// Using express-validator
const { body, param, query, validationResult } = require('express-validator');

app.get('/users',
  query('page').isInt({ min: 1, max: 100 }),
  query('limit').isInt({ min: 1, max: 50 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Safe to process validated input
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;

    // ... rest of logic
  }
);
```

---

### 4. ❌ Missing Content Security Policy - **HIGH**

**OWASP Category:** A05:2021 - Security Misconfiguration

**Risk:** XSS attacks, data exfiltration via malicious scripts.

**Current Code:**
```javascript
res.json([...]);
```

**Vulnerability:** No CSP headers to restrict script execution.

**Recommendation:**
```javascript
// Install helmet for security headers
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
    }
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: { policy: 'same-origin' },
  crossOriginResourcePolicy: { policy: 'same-origin' },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  xssFilter: true,
  noSniff: true,
}));
```

---

### 5. ❌ Missing Helmet Security Headers - **HIGH**

**OWASP Category:** A05:2021 - Security Misconfiguration

**Risk:** Multiple header-related vulnerabilities exposed.

**Vulnerability:** Missing essential HTTP security headers.

**Recommendation:**
```javascript
const helmet = require('helmet');

app.use(helmet({
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  disablePoweredBy: true,
  noCache: true
}));
```

---

### 6. ❌ No Authentication - **CRITICAL**

**OWASP Category:** A07:2021 - Identification and Authentication Failures

**Risk:** Anyone can access all endpoints without authorization.

**Current Code:**
```javascript
app.get('/health', (req, res) => {...});
app.get('/users', (req, res) => {...});
```

**Vulnerability:** Zero authentication - completely open to all.

**Recommendation:**
```javascript
const passport = require('passport');
const JwtStrategy = require('passport-jwt').Strategy;

// Secret should be in environment variables
const jwtSecret = process.env.JWT_SECRET || 'change_this_secret';

const opts = {
  jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
  secretOrKey: jwtSecret
};

passport.use(new JwtStrategy(opts, (jwtPayload, done) => {
  User.findById(jwtPayload.sub)
    .then(user => done(null, user))
    .catch(err => done(err, null));
}));

const requireAuth = passport.authenticate('jwt', { session: false });

// Protect sensitive endpoints
app.get('/users', requireAuth, (req, res) => {...});
```

---

### 7. ❌ Missing HTTPS/SSL - **CRITICAL**

**OWASP Category:** A01:2021 - Broken Access Control

**Risk:** Man-in-the-middle attacks, credential theft over HTTP.

**Current Code:**
```javascript
app.listen(3000, () => {...});
```

**Vulnerability:** Running on HTTP, no encryption.

**Recommendation:**
```javascript
const fs = require('fs');
const https = require('https');

const httpsOptions = {
  key: fs.readFileSync('security/cert.key'),
  cert: fs.readFileSync('security/cert.pem')
};

if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.protocol === 'http') {
      return res.redirect(301, 'https://' + req.headers.host + req.url);
    }
    next();
  });
}

https.createServer(httpsOptions, app).listen(443, () => {
  console.log('Secure server running on port 443');
});

// Keep HTTP for testing/dev
app.listen(3000, () => {
  console.log('Debug server running on port 3000');
});
```

---

### 8. ❌ No Input Sanitization - **HIGH**

**OWASP Category:** A03:2021 - Injection

**Risk:** XSS attacks if user input is rendered unsanitized.

**Current Code:**
```javascript
res.json([
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
]);
```

**Vulnerability:** Potential XSS in JSON data if names contain scripts.

**Recommendation:**
```javascript
const sanitizeHtml = require('sanitize-html');

const sanitize = (data) => {
  if (typeof data === 'string') {
    return sanitizeHtml(data, {
      allowedTags: [],
      allowedAttributes: {}
    });
  }
  if (Array.isArray(data)) {
    return data.map(item => sanitize(item));
  }
  if (typeof data === 'object') {
    const sanitized = {};
    for (const [key, value] of Object.entries(data)) {
      sanitized[key] = sanitize(value);
    }
    return sanitized;
  }
  return data;
};

// Apply sanitization before returning
app.get('/users', (req, res) => {
  res.json(sanitize([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]));
});
```

---

### 9. ❌ No Request Logging/Monitoring - **MEDIUM**

**OWASP Category:** A09:2021 - Security Logging and Monitoring Failures

**Risk:** Difficulty detecting and responding to attacks in real-time.

**Current Code:**
```javascript
console.log('Server running on port 3000');
```

**Vulnerability:** No logging for security events, audits, or incident response.

**Recommendation:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// Security-focused logging
const securityLogger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [new winston.transports.File({ filename: 'logs/security.log' })]
});

// Log all requests with user info
const accessLog = morgan('combined');

app.use((req, res, next) => {
  // Anonymize sensitive data
  const now = new Date().toISOString();
  securityLogger.info({
    timestamp: now,
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.headers['user-agent'],
    query: req.query,
    // Don't log body
  });

  // Log errors
  res.on('finish', () => {
    if (res.statusCode >= 400) {
      securityLogger.warn({
        timestamp: new Date().toISOString(),
        method: req.method,
        path: req.path,
        status: res.statusCode,
        ip: req.ip
      });
    }
  });

  next();
});

app.use(accessLog);
```

---

### 10. ❌ Missing Error Handling - **MEDIUM**

**OWASP Category:** A05:2021 - Security Misconfiguration

**Risk:** Information leakage through unhandled exceptions.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Vulnerability:** Crashes expose stack traces and internal details.

**Recommendation:**
```javascript
const { body, validationResult } = require('express-validator');

// Global error handler
app.use((err, req, res, next) => {
  // Don't log sensitive data
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    error: {
      name: err.name,
      message: process.env.NODE_ENV === 'development'
        ? err.message
        : 'An internal error occurred'
    }
  });
});

// Protected route with error handling
app.get('/users', [
  body('id').isInt(),
], (req, res) => {
  // Check validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  try {
    const validatedId = req.params.id;
    // ... secure logic
  } catch (err) {
    throw new AppError('Failed to retrieve user', 500);
  }
});
```

---

### 11. ❌ No Information Disclosure Protection - **MEDIUM**

**OWASP Category:** A05:2021 - Security Misconfiguration

**Risk:** Leaks sensitive information via error messages.

**Vulnerability:** No special error pages, public stack traces.

**Recommendation:**
```javascript
// Custom error handler to avoid information disclosure
const { body, validationResult } = require('express-validator');

app.use((err, req, res, next) => {
  // Log actual error
  console.error('Error:', err);

  // Generic error response
  if (err.statusCode) {
    return res.status(err.statusCode).json({
      error: err.message || 'An error occurred'
    });
  }

  // Generic 500 response
  res.status(500).json({
    error: 'An internal error occurred'
  });
});

// Environment-based configuration
if (process.env.NODE_ENV === 'development') {
  // Show detailed errors in dev
  app.use((err, req, res, next) => {
    res.status(err.statusCode || 500).json({
      ...err,
      stack: err.stack
    });
  });
}
```

---

### 12. ❌ No Request Body Size Limit - **MEDIUM**

**OWASP Category:** A06:2021 - Vulnerable and Outdated Components

**Risk:** Denial of service via oversized request bodies, memory exhaustion.

**Current Code:**
```javascript
