const app = express();
```

**Vulnerability:** No body size limits, vulnerable to DoS.

**Recommendation:**
```javascript
const bodyParser = require('body-parser');

// Limit request size
app.use(bodyParser.json({ limit: '1mb' }));
app.use(bodyParser.urlencoded({ limit: '1mb', extended: true }));

// OR using express.json():
app.use(express.json({
  limit: '1mb',
  verify: (req, res, buf) => {
    // Verify content type before size check
    if (req.path !== '/api/upload' || !req.is('application/json')) {
      return;
    }

    // Detect potential injection attempts (e.g., very long strings)
    if (buf.length > 1000000) { // 1MB threshold
      throw new Error('Payload too large');
    }
  }
}));
```

