const app = express();
```

**Vulnerability:** No validation of environment variables.

**Recommendation:**
```javascript
require('dotenv').config();

const envSchema = {
  PORT: { type: 'number', required: true, fallback: 3000 },
  NODE_ENV: { type: 'string', required: true, fallback: 'development', allowed: ['development', 'production', 'test'] },
  JWT_SECRET: { type: 'string', required: true },
  DATABASE_URL: { type: 'string', required: true },
  SECRET_KEY: { type: 'string', required: true },
  CORS_ORIGIN: { type: 'string', required: true }
};

// Validate environment variables
function validateEnv() {
  const errors = [];

  for (const [key, config] of Object.entries(envSchema)) {
    const value = process.env[key];

    if (config.required && !value) {
      errors.push(`Missing required environment variable: ${key}`);
      continue;
    }

    if (value && config.type === 'number') {
      const num = Number(value);
      if (isNaN(num)) {
        errors.push(`Invalid number for environment variable: ${key}`);
      }
    }

    if (value && config.allowed && !config.allowed.includes(value)) {
      errors.push(`Invalid value for ${key}. Must be one of: ${config.allowed.join(', ')}`);
    }
  }

  if (errors.length > 0) {
    console.error('Environment validation failed:');
    errors.forEach(err => console.error(`  - ${err}`));
    process.exit(1);
  }
}

validateEnv();

// Now safe to use process.env
const PORT = process.env.PORT;
const NODE_ENV = process.env.NODE_ENV;
```

