// security.js - Secure secret loader
class SecureSecretsManager {
  constructor() {
    if (process.env.NODE_ENV === 'development') {
      this.mode = 'development';
      // Only load env vars, but warn about usage
      console.warn('⚠️  Running in development - Secrets may be exposed');
    } else {
      this.mode = 'production';
      // Load from secrets manager
    }
  }

  async initialize() {
    const secrets = await this.fetchSecrets();
    this.secrets = secrets;
  }

  async fetchSecrets() {
    switch (process.env.SECRET_PROVIDER) {
      case 'aws':
        return await this.getAWSSecrets();
      case 'vault':
        return await this.getVaultSecrets();
      case 'azure':
        return await this.getAzureSecrets();
      default:
        throw new Error('No secret provider configured');
    }
  }

  async getAWSSecrets() {
    const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
    const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

    const commands = [
      'production/database',
      'production/aws',
      'production/payment',
      'production/ai'
    ].map(name => new GetSecretValueCommand({ SecretId: name }));

    const responses = await Promise.all(
      commands.map(cmd => client.send(cmd))
    );

    return responses.reduce((acc, res, i) => {
      acc[commands[i]['SecretId'].split('/')[1]] = JSON.parse(res.SecretString);
      return acc;
    }, {});
  }

  get(key) {
    if (!this.secrets) {
      throw new Error('Secrets not initialized');
    }
    return this.secrets[key] || process.env[key];
  }

  dispose() {
    // Clear secrets from memory
    this.secrets = null;
  }
}

