# Security Audit Report for app.js

## Executive Summary
The application is a minimal Express.js server with basic routes. While the code is simple and appears to be a demonstration/mock setup, **it contains several critical security vulnerabilities** that would need to be addressed in a production environment.

---

## Severity Breakdown

| Severity | Vulnerability | Status |
|----------|---------------|--------|
| 🔴 High | Authentication Missing | Critical |
| 🔴 High | Input Validation Missing | Critical |
| 🟡 Medium | Lack of CORS Configuration | High |
| 🟡 Medium | No Rate Limiting | High |
| 🟡 Medium | Missing Security Headers | Medium |
| 🟢 Low | No SQL Injection Protection | Low |

---

## Detailed Findings

---

## 1. 🔴 HIGH: Authentication and Authorization Missing

**Issue:** All routes are publicly accessible without any authentication mechanism.

**Risk:** Anyone can access `/health` and `/users` endpoints, regardless of who they are.

**Example Attack:**
```bash
# Attacker can scan your application
curl http://your-server.com/health
curl http://your-server.com/users

# JSON response can be captured for intelligence gathering
curl http://your-server.com/users -o users.json
```

**Recommendation:** Implement authentication middleware

```javascript
// Recommended: JWT-based authentication
const jwt = require('jsonwebtoken');
const express = require('express');
const app = express();

// Configure JWT secret in environment variable (NOT hardcoded)
const JWT_SECRET = process.env.JWT_SECRET || 'change_this_in_production';
const PORT = process.env.PORT || 3000;

// Middleware to verify JWT
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// Protected route example
app.get('/users', authenticateToken, (req, res) => {
  // Only authenticated users can see this
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

// Login endpoint with proper password hashing
const bcrypt = require('bcrypt');
app.post('/login', async (req, res) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password required' });
  }

  // Mock user lookup - in production, query your database
  const user = { id: 1, username: 'admin', passwordHash: await bcrypt.hash('securePassword123', 10) };

  try {
    const match = await bcrypt.compare(password, user.passwordHash);
    if (match) {
      const token = jwt.sign(
        { userId: user.id, username: user.username },
        JWT_SECRET,
        { expiresIn: '24h' }
      );
      return res.json({ token, userId: user.id, username: user.username });
    }
  } catch (error) {
    return res.status(500).json({ error: 'Authentication failed' });
  }

  return res.status(401).json({ error: 'Invalid credentials' });
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

**Also read docs on OAuth2, API keys, or session-based auth depending on your use case.**

---

## 2. 🔴 HIGH: Missing Input Validation

**Issue:** No validation of request parameters of sensitive types (query parameters, body data, path parameters) before using them.

**Risk:**
- Path traversal attacks
- Parameter pollution
- Data corruption
- Potential for indirect injection

**Example Attacks:**

```bash
# Path Traversal
curl http://your-server.com/users/../../etc/passwd
# In production with file operations, this could read system files

# Parameter Pollution
curl "http://your-server.com/users?id=1&id=2&id=99999999999999999999"

# SQL Injection (if eventually used with DB)
curl "http://your-server.com/users?id=1' OR '1'='1"
```

**Recommendation:** Use validation middleware (express-validator or Joi)

```javascript
const express = require('express');
const { body, param, query, validationResult } = require('express-validator');
const app = express();

// Validation middleware generator
function validate(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
}

// Example: Validate query parameter
app.get(
  '/users',
  [query('page').isInt({ min: 1 }).withMessage('Page must be a positive integer'),
   query('limit').isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')],
  validate,
  (req, res) => {
    const { page = 1, limit = 10 } = req.query;
    res.json({ page, limit });
  }
);

// Example: Validate route parameter
app.get(
  '/users/:id',
  [param('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer')],
  validate,
  (req, res) => {
    const userId = parseInt(req.params.id);
    res.json({ id: userId });
  }
);

// Example: Validate request body
app.post(
  '/users',
  [body('email').isEmail().withMessage('Invalid email format'),
   body('name').isLength({ min: 2, max: 50 }).trim().withMessage('Name must be 2-50 characters')],
  validate,
  (req, res) => {
    const { email, name } = req.body;
    // Create user...
    res.status(201).json({ email, name });
  }
);
```

**Important:** Use `escape()` or `sanitize()` for escaping user input when rendering HTML, to protect against XSS.

---

## 3. 🟡 MEDIUM: Lack of CORS Configuration

**Issue:** No CORS middleware configured, allowing any origin to access the API.

**Risk:** XSS could steal data from authenticated sessions, or CSRF attacks if forms are involved.

**Recommendation:** Configure CORS with allowed origins

```javascript
const cors = require('cors');
const app = express();

// Secure CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// More specific CORS (for different routes)
app.options('/api/protected', cors({
  origin: 'https://your-allowed-domain.com',
  methods: ['GET', 'POST'],
  credentials: true
}));
```

---

## 4. 🟡 MEDIUM: No Rate Limiting

**Issue:** No rate limiting, allowing unlimited request volume.

**Risk:**
- Denial of Service (DoS) attacks
- Brute force attacks on endpoints
- Resource exhaustion

**Recommendation:** Implement rate limiting

```javascript
const rateLimit = require('express-rate-limit');
const app = express();

// General API rate limiter
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});

// Login rate limiter - more strict
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // limit to 5 attempts per windowMs
  skipSuccessfulRequests: true, // only limit failed attempts
  message: 'Too many login attempts, please try again later.'
});

// Apply to all API routes
app.use('/api', apiLimiter);

// Apply specifically to login route
app.post('/login', loginLimiter, (req, res) => {
  // Auth logic
});

// Strict rate limiter for sensitive operations
const strictLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 20, // 20 requests per hour
  message: 'Rate limit exceeded, please contact support.'
});

app.use('/admin', strictLimiter);
```

---

## 5. 🟡 MEDIUM: Missing Security Headers

**Issue:** No security headers configured to protect against common attacks.

**Risk:**
- Clickjacking
- Cross-site script injection (XSS)
- Cookie theft
- MIME sniffing

**Recommendation:** Add security headers

```javascript
const helmet = require('helmet');
const app = express();

// Helmet auto-configures many security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'", "'unsafe-eval'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    }
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: "same-site" },
  referrerPolicy: { policy: "strict-origin-when-cross-origin" }
}));

// Additional security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=63072000; includeSubDomains; preload');
  res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
  next();
});
```

---

## 6. 🟢 LOW: No SQL Injection Protection

**Issue:** While not directly vulnerable in current code (no database), proper parameterized queries should be used when DB interactions are added.

**Risk:** SQL injection if raw SQL queries are used without parameterization.

**Recommendation:** Use parameterized queries

```javascript
// Bad - Vulnerable to SQL Injection
const query = `SELECT * FROM users WHERE id = ${req.params.id}`;
db.query(query, (err, results) => { ... });

// Good - Parameterized query (safe)
const query = 'SELECT * FROM users WHERE id = $1';
db.query(query, [req.params.id], (err, results) => { ... });

// Or use ORMs (even better)
const User = require('./models/User').default;

// With Sequelize example:
// const user = await User.findOne({ where: { id: req.params.id } });

// With Mongoose example:
// const user = await User.findById(req.params.id);
```

---

## 7. 🟢 LOW: No Input Sanitization

**Issue:** User input is not sanitized before being sent in responses (if rendered to HTML).

**Risk:** XSS attacks in HTML responses.

**Recommendation:** Sanitize user input

```javascript
const sanitizeHtml = require('sanitize-html');

app.get('/users', (req, res) => {
  const cleanName = sanitizeHtml(req.query.name || '', {
    allowedTags: [],
    allowedAttributes: {}
  });

  res.send(`
    <h1>User: ${escapeHtml(req.query.name || 'Unknown')}</h1>
    <p>Email: ${escapeHtml(req.query.email || '')}</p>
  `);
});

// Helper function
function escapeHtml(text) {
  if (!text) return '';
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}
```

---

