// Centralized logging utility using Winston

const winston = require('winston');
const path = require('path');

const logFormat = winston.format.combine(
  winston.format.timestamp({
    format: 'YYYY-MM-DD HH:mm:ss',
  }),
  winston.format.errors({ stack: true }),
  winston.format.splat(),
  winston.format.json()
);

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || (process.env.NODE_ENV === 'production' ? 'info' : 'debug'),
  format: logFormat,
  defaultMeta: { service: 'api-server' },
  transports: [
    // Write all logs with importance level of `error` or less to `error.log`
    new winston.transports.File({ filename: path.join(__dirname, '../../logs/error.log'), level: 'error' }),
    // Write all logs to `combined.log`
    new winston.transports.File({ filename: path.join(__dirname, '../../logs/combined.log') }),
  ],
});

// If we're not in production, also log to the console with a simple format
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.combine(
      winston.format.colorize(),
      winston.format.simple(),
    ),
  }));
}

// Convenience methods
logger.info = (...args) => logger.log('info', ...args);
logger.debug = (...args) => logger.log('debug', ...args);
logger.warn = (...args) => logger.log('warn', ...args);
logger.error = (...args) => logger.log('error', ...args);

// Request logging middleware
function requestLogger(req, res, next) {
  const startTime = Date.now();

  // Log request
  logger.info('Incoming request', {
    method: req.method,
    url: req.path,
    ip: req.ip,
    userAgent: req.get('user-agent'),
  });

  // Capture response data
  const originalSend = res.send;
  res.send = function (data) {
    const duration = Date.now() - startTime;
    res.responseTime = `${duration}ms`;

    logger.info('Request completed', {
      method: req.method,
      url: req.path,
      statusCode: res.statusCode,
      duration,
      ip: req.ip,
    });

    // Preserve original send behavior
    return originalSend.call(this, data);
  };

  next();
}

module.exports = { logger, requestLogger };

// File: utils/errors.js
// Custom error classes and error handling middleware

class AppError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true; // Helps distinguish operational errors from programming errors

    Error.captureStackTrace(this, this.constructor);
  }
}

class NotFoundError extends AppError {
  constructor(message = 'Resource not found') {
    super(message, 404);
  }
}

class UnauthorizedError extends AppError {
  constructor(message = 'Unauthorized') {
    super(message, 401);
  }
}

class ForbiddenError extends AppError {
  constructor(message = 'Forbidden') {
    super(message, 403);
  }
}

class ValidationError extends AppError {
  constructor(message = 'Validation failed', details = []) {
    super(message, 422);
    this.details = details;
  }
}

// Global error handler middleware
function errorHandler(err, req, res, next) {
  // Log the error for debugging
  if (err.isOperational === false) {
    // Programming or unknown errors get logged and stack trace
    console.error(err.stack);
  } else {
    // Operational errors are logged normally
    console.error(err);
  }

  // Production vs Development error handling
  if (process.env.NODE_ENV === 'production' && err.isOperational === false) {
    let error = new Error('Something went wrong');
    return res.status(500).json({
      status: 'error',
      message: error.message,
    });
  }

  // Development errors respond with stack trace
  if (process.env.NODE_ENV === 'development') {
    return res.status(err.statusCode || 500).json({
      status: err.status || 'error',
      message: err.message,
      stack: err.stack,
      ...(err.details && { details: err.details }), // Add validation details if present
      error: err.name,
    });
  }

  // Default response for other cases
  return res.status(err.statusCode || 500).json({
    status: err.status || 'error',
    message: err.message,
  });
}

// Development-only error handler (not exported in production)
function developmentOnly errorHandler(err, req, res, next) {
  const statusCode = err.statusCode || 500;
  console.error(err.stack);

  res.status(statusCode).json({
    status: err.status || 'error',
    message: err.message,
    stack: err.stack,
    error: err.name,
  });
}

// Async handler wrapper to catch errors in async route handlers
function asyncHandler(fn) {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

module.exports = {
  AppError,
  NotFoundError,
  UnauthorizedError,
  ForbiddenError,
  ValidationError,
  errorHandler,
  developmentOnly,
  asyncHandler,
};

