);

// Also apply DOMPurify if rendering HTML content
const DOMPurify = require('isomorphic-dompurify');
app.post('/posts', (req, res) => {
  const cleanContent = DOMPurify.sanitize(req.body.content);
  // Save cleanContent to database
});
