# Security Review Report - app.js

## Executive Summary
The current implementation of app.js has **critical security vulnerabilities** that expose the application to multiple OWASP Top 10 risks. The application serves as an unsecured REST API with no authentication, validation, or protection mechanisms.

---

## Critical Vulnerabilities

### 1. **Broken Access Control (A01:2021)**
**Severity:** 🔴 CRITICAL

**Issue:** No authentication or authorization is implemented. Any client (including untrusted users) can access all endpoints.

**Vulnerability:**
- No login mechanism
- No role-based access control (RBAC)
- No session management
- No API key authentication

**Attack Scenarios:**
- Malicious actors can enumerate user data
- Authentication bypass
- Authorization bypass for administrative functions
- Data exfiltration

**Code Example of Vulnerable Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommendation:**
```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const app = express();
const SECRET_KEY = process.env.JWT_SECRET;

// Middleware for authentication
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, SECRET_KEY, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Middleware for admin authorization
const requireAdmin = (req, res, next) => {
  if (!req.user?.isAdmin) {
    return res.status(403).json({ error: 'Admin access required' });
  }
  next();
};

app.get('/users', authenticateToken, (req, res) => {
  // Only authenticated users can access user data
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.post('/register', async (req, res) => {
  try {
    const { username, password, email } = req.body;

    // Validate input
    if (!username || !password || !email) {
      return res.status(400).json({ error: 'All fields are required' });
    }

    // Validate username format
    if (username.length < 3) {
      return res.status(400).json({ error: 'Username must be at least 3 characters' });
    }

    // Email validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return res.status(400).json({ error: 'Invalid email format' });
    }

    // Check if user already exists
    const existingUser = await User.findOne({ email });
    if (existingUser) {
      return res.status(409).json({ error: 'Email already registered' });
    }

    // Hash password
    const hashedPassword = await bcrypt.hash(password, 12);

    // Create user
    const user = await User.create({
      username,
      email,
      password: hashedPassword,
    });

    // Generate JWT
    const token = jwt.sign(
      { userId: user._id, username: user.username },
      SECRET_KEY,
      { expiresIn: '24h' }
    );

    res.status(201).json({ token, user: { id: user._id, username: user.username, email: user.email } });
  } catch (error) {
    console.error('Register error:', error);
    res.status(500).json({ error: 'Registration failed' });
  }
});

app.post('/login', async (req, res) => {
  try {
    const { username, password } = req.body;

    if (!username || !password) {
      return res.status(400).json({ error: 'Username and password required' });
    }

    // Find user
    const user = await User.findOne({ username });
    if (!user) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Verify password
    const isValidPassword = await bcrypt.compare(password, user.password);
    if (!isValidPassword) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Generate JWT
    const token = jwt.sign(
      { userId: user._id, username: user.username, isAdmin: user.isAdmin },
      SECRET_KEY,
      { expiresIn: '24h' }
    );

    res.json({ token });
  } catch (error) {
    console.error('Login error:', error);
    res.status(500).json({ error: 'Login failed' });
  }
});
```

---

### 2. **Broken Access Control (A01:2021) - Server-Side Request Forgery (SSRF) Risk**
**Severity:** 🔴 HIGH

**Issue:** The `/health` endpoint exposes internal server information without rate limiting.

**Vulnerability:**
- Sensitive information exposure
- No rate limiting
- No CORS configuration
- Information disclosure

**Attack Scenarios:**
- Information gathering for targeted attacks
- SSRF via related endpoints
- Downtime via repeated requests

**Code Example of Vulnerable Code:**
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

// Security headers middleware
const helmet = require('helmet');
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply to all routes
app.use(limiter);

// Secure health endpoint
app.get('/health', limiter, authenticateToken, (req, res) => {
  // Only authenticated users
  res.json({
    status: 'ok',
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
    version: process.env.API_VERSION || '1.0.0'
  });
});

// Rate limiting for sensitive endpoints
const sensitiveLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 10, // 10 requests per hour
});

// Apply to all endpoints
app.get('/users', sensitiveLimiter, ...);
```

---

### 3. **Injection (A03:2021)** - Cross-Site Scripting (XSS)
**Severity:** 🟡 MEDIUM-HIGH

**Issue:** No input validation or sanitization for any user input.

**Vulnerabilities:**
- No HTML entity encoding
- No DOMPurify for React/Vue
- Script injection in responses
- No Content-Security-Policy headers

**Attack Scenarios:**
- Stored XSS in user data
- Reflected XSS through query parameters
- DOM-based XSS in client-side rendering

**Code Example of Vulnerable Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommendation:**
```javascript
const express = require('express');
const { body, validationResult } = require('express-validator');
const DOMPurify = require('isomorphic-dompurify');
const app = express();

// Custom validator for safe HTML
const sanitizeHtml = (input) => {
  if (typeof input !== 'string') return input;
  return DOMPurify.sanitize(input);
};

// Input validation middleware
const validateUserInput = [
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 3, max: 100 }).withMessage('Name must be 3-100 characters')
    .matches(/^[a-zA-Z\s-]+$/).withMessage('Name can only contain letters, spaces, and hyphens'),
  body('email')
    .trim()
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format')
    .normalizeEmail(),
  body('username')
    .trim()
    .notEmpty().withMessage('Username is required')
    .matches(/^[a-zA-Z0-9_]+$/).withMessage('Only alphanumeric characters and underscores allowed'),
  body('password')
    .isLength({ min: 12 }).withMessage('Password must be at least 12 characters')
    .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/).withMessage('Must contain uppercase, lowercase, and number'),
];

// Sanitize middleware
const sanitizeBody = (req, res, next) => {
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        req.body[key] = sanitizeHtml(req.body[key]);
      }
    });
  }
  next();
};

app.use(express.json({ limit: '10kb' })); // Prevent oversized payloads

app.post('/users', validateUserInput, sanitizeBody, (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { name, email, username } = req.body;
  res.json({ id: Date.now(), name: sanitizeHtml(name), email, username });
});

app.get('/users/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const user = users.find(u => u.id === id);

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  // Sanitize before sending
  res.json({
    id: user.id,
    name: sanitizeHtml(user.name),
    email: sanitizeHtml(user.email)
  });
});
```

---

### 4. **Cryptographic Failures (A02:2021)**
**Severity:** 🔴 HIGH

