```javascript
// bin/secrets-loader.js
const path = require('path');
const { config } = require('dotenv');
const fs = require('fs');

module.exports = async () => {
  // 1. Validate NODE_ENV
  if (!process.env.NODE_ENV) {
    console.warn('⚠️  NODE_ENV not set, defaulting to development');
    process.env.NODE_ENV = 'development';
  }

  // 2. Load base .env (template)
  try {
    await config({
      path: path.join(__dirname, '../.env.example'),
      override: false,
    });
  } catch (error) {
    console.warn('⚠️  .env.example not found, using defaults');
  }

  // 3. Load environment-specific secrets
  const env = process.env.NODE_ENV;
  const envFiles = [
    { path: `./.secrets/.env.${env}.local`, priority: 3 },
    { path: `./.secrets/.env.${env}`, priority: 2 },
    { path: './.env', priority: 1 },
  ];

  if (env === 'production') {
    envFiles.push({ path: './.secrets/.env.production', priority: 3 });
  }

  // 4. Sort and load files in priority order
  for (const { path: filePath, priority } of envFiles.sort((a, b) => b.priority - a.priority)) {
    const fullPath = path.join(__dirname, `../${filePath}`);

    if (fs.existsSync(fullPath)) {
      try {
        // Log but don't print secrets (in production)
        if (process.env.DEBUG_SECRET_LOADING) {
          const lines = fs.readFileSync(fullPath, 'utf-8');
          const secretCount = lines.split('\n').filter(l => l.includes('=')).length;
          console.log(`🔓 Loading ${filePath} (${secretCount} secrets)...`);
        }

        await config({ path: fullPath, override: true });
      } catch (error) {
        console.error(`❌ Failed to load ${filePath}:`, error.message);
        process.exit(1);
      }
    }
  }

  // 5. Validate secrets
  return validateSecrets();
};

function validateSecrets() {
  const required = [
    { key: 'DATABASE_URL', name: 'Database Connection URL', requiredFor: ['development', 'production'] },
    { key: 'JWT_SECRET', name: 'JWT Secret', requiredFor: ['development', 'production'] },
    { key: 'AWS_ACCESS_KEY_ID', name: 'AWS Access Key', requiredFor: ['production'] },
    { key: 'AWS_SECRET_ACCESS_KEY', name: 'AWS Secret Key', requiredFor: ['production'] },
    { key: 'ANTHROPIC_API_KEY', name: 'Anthropic API Key', requiredFor: ['production'] },
    { key: 'STRIPE_SECRET_KEY', name: 'Stripe Secret Key', requiredFor: ['production'] },
  ];

  if (process.env.NODE_ENV === 'development') {
    // Development allows missing prod secrets but throws on data-service secrets
    return validateDev(required);
  } else {
    // Production: All required
    return validateProd(required);
  }
}

function validateDev(required) {
  const valid = required.filter(({ key }) => process.env[key]);

  if (valid.length === 0) {
    console.warn('⚠️  No secrets loaded in development mode, will use fallback values');
    return true;
  }

  console.log(`✅ Loaded ${valid.length} development secrets`);
  return true;
}

function validateProd(required) {
  const missing = required.filter(({ key }) => !process.env[key]);

  if (missing.length > 0) {
    console.error('❌ Missing production secrets:', missing.map(s => s.name));
    process.exit(1);
  }

  console.log(`✅ Loaded ${required.length} production secrets`);
  return true;
}
```

