## 🔴 Security Findings

### 1. **No Authentication or Authorization**
**Severity:** High  
**OWASP:** A01:2021 - Broken Access Control

The `/users` endpoint exposes user data to everyone without any authentication mechanism.

```javascript
// ❌ CURRENT VULNERABLE CODE
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Risk:** Anyone can scrape all user data from this API, including Personally Identifiable Information (PII).

**Recommendation:**
```javascript
const passport = require('passport');
const jwt = require('jsonwebtoken');

// JWT Strategy
passport.use(new JwtStrategy({
  jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
  secretOrKey: process.env.JWT_SECRET
}, (jwtPayload, done) => {
  // Verify JWT and return user
  return done(null, getUserById(jwtPayload.userId));
}));

// Protected route
app.get('/users', ensureAuthenticated, async (req, res) => {
  // Filter users based on role or access
  const users = await getUsersForAuthenticatedUser(req.user.id);
  res.json(users);
});

// Middleware
function ensureAuthenticated(req, res, next) {
  if (req.isAuthenticated()) {
    return next();
  }
  res.status(401).json({ error: 'Unauthorized' });
}
```

---

### 2. **Missing Input Validation**
**Severity:** Medium  
**OWASP:** A03:2021 - Injection

No validation on request parameters, routing, or data handling.

```javascript
// ❌ CURRENT - No validation
app.get('/users', (req, res) => {
  res.json([...]);
});

// ✅ RECOMMENDED - Add validation
const { param, query, validationResult, body } = require('express-validator');

app.get('/users', [
  // Validate user ID parameter if used
  param('userId').isInt({ min: 1 }).withMessage('Valid user ID required'),

  // Validate optional query parameters
  query('page').optional().isInt({ min: 1 }).withMessage('Invalid page number'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Invalid limit'),

  // Validate sort parameter
  query('sort').optional().isIn(['name', 'email', 'id']).withMessage('Invalid sort field'),
], async (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Safe to use validated parameters
  const page = parseInt(req.query.page) || 1;
  const limit = Math.min(parseInt(req.query.limit) || 10, 100);

  res.json([...]);
});
```

---

### 3. **Path Traversal Risk (if endpoints expanded)**
**Severity:** Medium  
**OWASP:** A01:2021 - Broken Access Control

If dynamic file serving is added but no sanitization is implemented, attackers can access any file on the server.

**Recommendation:**
```javascript
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');

app.get('/files/:filename', async (req, res) => {
  const { filename } = req.params;

  // Validate filename to prevent path traversal attacks
  if (!filename || filename.includes('..') || filename.includes('/') || filename.includes('\\')) {
    return res.status(400).json({ error: 'Invalid filename' });
  }

  // Use hash for safety instead of raw filename
  const safeFilename = crypto.createHash('sha256').update(filename).digest('hex');
  const filePath = path.join(__dirname, 'uploads', safeFilename);

  if (fs.existsSync(filePath)) {
    const fileStream = fs.createReadStream(filePath);
    fileStream.pipe(res);
  } else {
    res.status(404).json({ error: 'File not found' });
  }
});
```

