let users = [];

app.get('/users', cors({
  origin: function(origin, callback) {
    // Allow requests with no origin (like mobile apps)
    if (!origin) return callback(null, true);

    const allowedOrigins = [
      process.env.CORS_ORIGIN ? process.env.CORS_ORIGIN : 'http://localhost:3000',
