### 5. **No Encryption for Sensitive Data**
**Severity:** Medium  
**OWASP:** A02:2021 - Cryptographic Failures

User email addresses are exposed in plaintext JSON responses.

**Recommendation:**
```javascript
// Encrypt sensitive data before sending
const crypto = require('crypto');

const encryptionKey = process.env.ENCRYPTION_KEY;
const algorithm = 'aes-256-cbc';

function encrypt(text) {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv(algorithm, Buffer.from(encryptionKey, 'hex'), iv);
  const encrypted = Buffer.concat([cipher.update(text), cipher.final()]);
  return iv.toString('hex') + ':' + encrypted.toString('hex');
}

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: encrypt('alice@example.com') },
    { id: 2, name: 'Bob', email: encrypt('bob@example.com') }
  ]);
});
```

---

### 6. **No Rate Limiting (Even on Non-Authenticated Endpoints)**
**Severity:** High  
**OWASP:** A04:2021 - Insecure Design

No protection against DoS or brute force regardless of authentication.

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

// General rate limiting for all endpoints
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    error: 'Too many requests, please try again later.'
  }
});

app.use(limiter);

// Stricter rate limiting for /health (must be available everywhere)
const healthLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20, // 20 requests per 15 minutes
});

app.get('/health', healthLimiter, (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

---

### 7. **Missing Security Headers**
**Severity:** Medium  
**OWASP:** A05:2021 - Security Misconfiguration

No HSTS, X-Frame-Options, or other security headers set.

**Recommendation:**
```javascript
const helmet = require('helmet');

// Helmet sets multiple security headers
app.use(helmet());

// Optional: Set uppercase headers for legacy browsers
app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true
}));
app.use(helmet.frameguard({ action: 'sameorigin' }));
app.use(helmet.xssFilter());
app.use(helmet.noSniff());
```

---

### 8. **Debug Mode Exposed**
**Severity:** Low  
**OWASP:** A05:2021 - Security Misconfiguration

No check for production vs development mode.

**Recommendation:**
```javascript
const isProduction = process.env.NODE_ENV === 'production';

if (isProduction) {
  console.log('Server running in production mode');

  // In production, avoid logging sensitive operations
  app.use((req, res, next) => {
    if (req.url === '/health' || req.method === 'GET') {
      next();
    } else {
      // Log auth operations, SQL queries, etc. for production
      next();
    }
  });
} else {
  console.log('Server running in development mode');
  // In development, show detailed error logs
}
```

---

### 9. **No Service Endpoint Protection**
**Severity:** High  
**OWASP:** A01:2021 - Broken Access Control

`app.listen()` is called unconditionally and allows anyone to test endpoints on port 3000.

**Recommendation:**
```javascript
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Instead of listening immediately, use a graceful shutdown handler
let server;

function startServer() {
  server = app.listen(PORT, HOST, () => {
    console.log(`Server running on http://${HOST}:${PORT}`);
  });

  // Graceful shutdown on SIGTERM/SIGINT
  process.on('SIGTERM', () => {
    console.log('SIGTERM received, shutting down gracefully...');
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });
  });

  process.on('SIGINT', () => {
    console.log('SIGINT received, shutting down gracefully...');
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });
  });
}

// Start only in development or if explicitly allowed in production
if (process.env.ALLOW_LIVE_TESTING === 'true' || process.env.NODE_ENV === 'development') {
  startServer();
} else {
  console.log('Server will not listening. Set ALLOW_LIVE_TESTING=true to run.');
}
```

