| Logfire | `LOGFIRE_TOKEN` | `CANARY-logfire-token-1a3c5e7g` | Medium - Analytics token |

### ❌ CRITICAL ISSUES with Current Configuration

1. **Before applying code review fixes**, secrets would be loaded purely via:
   ```javascript
   require('dotenv').config()  // If added without proper validation
   ```

2. **Problems with basic dotenv usage:**
   - Secrets loaded into `process.env` in plaintext
   - No encryption/obfuscation
   - Stored in `.env` file (trouble with `.gitignore`)
   - No runtime protection against memory dumps
   - No secrets rotation capability

---

## 🛡️ Recommended Secrets Architecture

### 1. Environment Variables (For Local Development)
```javascript
// Load environment variables early
require('dotenv').config();

// Validate secrets exist
function validateRequiredSecrets() {
  const requiredSecrets = [
    'DATABASE_URL',
    'JWT_SECRET',
    'ENCRYPTION_KEY',
    'REDIS_URL',
    'SESSION_SECRET'
  ];

  const missing = requiredSecrets.filter(s => !process.env[s]);

  if (missing.length > 0) {
    console.error('❌ Missing required secrets:', missing.join(', '));
    process.exit(1);
  }
}

validateRequiredSecrets();
```

### 2. Secrets Manager for Production (Better than .env)

#### Option A: AWS Secrets Manager
```javascript
const AWS = require('aws-sdk');

async function loadAwsSecrets(region) {
  const client = new AWS.SecretsManager({ region });

  const secrets = {
    database: await client.getSecretValue({ SecretId: 'production/db-credentials' }).promise(),
    jwt: await client.getSecretValue({ SecretId: 'production/jwt-secret' }).promise(),
    stripe: await client.getSecretValue({ SecretId: 'production/stripe-key' }).promise(),
  };

  return secrets;
}

// Usage
const secrets = await loadAwsSecrets('us-east-1');
process.env.DATABASE_URL = secrets.database.SecretString;
process.env.JWT_SECRET = secrets.jwt.SecretString;
```

#### Option B: HashiCorp Vault
```javascript
import { Vault } from 'vault-1.1.3';

const vault = new Vault({
  endpoint: process.env.VAULT_URL,
  token: process.env.VAULT_TOKEN
});

async function loadVaultSecrets() {
  // Get secrets from Vault
  const dbSecret = await vault.read('secret/production/database');
  const jwtSecret = await vault.read('secret/production/jwt');
  const stripeSecret = await vault.read('secret/production/stripe');

  process.env.DATABASE_URL = dbSecret.data.password;
  process.env.JWT_SECRET = jwtSecret.data.password;
  process.env.STRIPE_KEY = stripeSecret.data.password;
}

loadVaultSecrets();
```

#### Option C: Google Secret Manager
```javascript
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

const client = new SecretManagerServiceClient();

async function loadGoogleSecrets() {
  const projectId = 'your-project-id';

  const [dbSecret] = await client.accessSecretVersion({
    name: `projects/${projectId}/secrets/database-credentials/versions/latest`,
  });

  const [jwtSecret] = await client.accessSecretVersion({
