  process.env.JWT_SECRET = jwtSecret.payload.data.toString('utf8');
}

loadGoogleSecrets();
```

### 3. Secrets Encryption/Locking During Runtime

#### Using aws-kms for Encryption
```javascript
const { KMSClient, DecryptCommand } = require('@aws-sdk/client-kms');

const kmsClient = new KMSClient({ region: 'us-east-1' });

async function decryptSecrets() {
  const encryptedSecrets = {
    DATABASE_URL: process.env.ENCRYPTED_DATABASE_URL,
    JWT_SECRET: process.env.ENCRYPTED_JWT_SECRET
  };

  const secrets = await Promise.all(
    Object.entries(encryptedSecrets).map(async ([key, ciphertext]) => {
      const response = await kmsClient.send(
        new DecryptCommand({ CiphertextBlob: Buffer.from(ciphertext, 'base64') })
      );
      return { [key]: response.Plaintext.toString('utf8') };
    })
  );

  return Object.assign({}, ...secrets);
}

// In config file
process.env.DATABASE_URL = await decryptSecrets().DATABASE_URL;
```

#### Using libvault for Runtime Secrets
```javascript
const vault = require('libvault');

const secretConfig = vault({
  vaultUrl: process.env.VAULT_URL,
  token: process.env.VAULT_TOKEN,
  kvVersion: 2
});

