## 🔒 Security Best Practices for Secrets Management

### 1. File Permissions
```bash
# Restrict .env file permissions
chmod 600 .env                    # Only owner can read/write
# On some systems:
chmod 640 .env && chown appuser:appuser .env
```

### 2. `.gitignore` Configuration
```gitignore
# Essential - Never commit secrets
.env
.env.local
.env.*.local
.env.test
.env.production

# IDE and editor files
.idea/
.vscode/
*.swp
*.swo

# OS files
.DS_Store
Thumbs.db
```

### 3. Runtime Process Guard
```javascript
const { execSync } = require('child_process');

function addProcessGuard() {
  try {
    // Prevent reading of process memory if secrets in env
    if (process.env.NODE_ENV === 'production') {
      const currentUid = process.getuid();
      const currentGid = process.getgid();

      // Try to make the process as limited as possible
      const euid = execSync('id -u').toString().trim();
      if (parseInt(euid) != currentUid) {
        console.warn('Running with elevated privileges possible');
      }
    }
  } catch (err) {
    console.error('Error checking process permissions:', err);
  }
}

addProcessGuard();

// Terminate on unauthorized memory access attempts
process.on('uncaughtException', (err) => {
  console.error('Unexpected error:', err);
  if (err.message.includes('Debuggee for ptrace') ||
      err.message.includes('Inspector')) {
    process.exit(1); // Prevent debugging attacks
  }
});
```

### 4. Secrets Rotation Setup
```javascript
// Every 24 hours, rotate secrets
const crypto = require('crypto');

function rotateSecret(secretName, oldSecret) {
  const newSecret = randomSecret(64); // 256-bit random value

  // Update in secrets manager
  await secretsManager.putSecretValue({
    SecretId: secretName,
    SecretString: newSecret
  });

  // Update application config rolling restart
  return newSecret;
}

function randomSecret(length) {
  return crypto.randomBytes(length / 2).toString('hex');
}
```

