### 🔴 **VULNERABILITY #4: No HSTS Header**

**Issue:** Missing HTTP Strict Transport Security to prevent protocol downgrades and man-in-the-middle attacks.

**Recommendation:** Add security headers using Helmet

```javascript
const helmet = require('helmet');

// Set security headers
app.use(helmet({
  contentSecurityPolicy: false, // Configure if needed
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  crossOriginEmbedderPolicy: { policy: "require-corp" },
  crossOriginOpenerPolicy: { policy: "same-origin" }
}));

// Or custom headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});
