### **5. Encrypt Secrets in Storage**

```javascript
// Install: npm install crypto
const crypto = require('crypto');
require('dotenv').config();

function encryptSecret(secret, encryptionKey) {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv('aes-256-gcm', Buffer.from(encryptionKey), iv);

  let encrypted = cipher.update(secret);
  encrypted = Buffer.concat([encrypted, cipher.final()]);

  const authTag = cipher.getAuthTag();

  return {
    iv: iv.toString('hex'),
    contents: encrypted.toString('hex'),
    authTag: authTag.toString('hex')
  };
}

function decryptSecret(encrypted, encryptionKey) {
  const iv = Buffer.from(encrypted.iv, 'hex');
  const decipher = crypto.createDecipheriv(
    'aes-256-gcm',
    Buffer.from(encryptionKey),
    iv
  );

  decipher.setAuthTag(Buffer.from(encrypted.authTag, 'hex'));

  let decrypted = decipher.update(Buffer.from(encrypted.contents, 'hex'));
  decrypted = Buffer.concat([decrypted, decipher.final()]);

  return decrypted.toString();
}

// Add encryption to app startup
const ENCRYPTION_KEY = process.env.ENCRYPTION_KEY; // 32-char hex key

