## 🔄 Implementing a Secrets Solution

```javascript
// Create: config/secrets.js
const dotenv = require('dotenv');
const path = require('path');

// Load environment-based config
dotenv.config({ path: path.join(__dirname, `../.env.${process.env.NODE_ENV || 'development'}`) });

// Validate required secrets by type
const validateSecrets = (envFile) => {
  const secrets = new Map();

  // DB secrets
  if (envFile.DATABASE_URL || (envFile.DATABASE_HOST && envFile.DATABASE_PASSWORD)) {
    const dbType = envFile.DATABASE_URL?.startsWith('postgres') ? 'postgres' : 'mysql';
    secrets.set('database', {
      type: dbType,
      url: envFile.DATABASE_URL || `${envFile.DATABASE_HOST}:${envFile.DATABASE_PORT}`,
      user: envFile.DATABASE_USER,
      host: envFile.DATABASE_HOST,
    });
  }

  // External service secrets
  if (envFile.ANTHROPIC_API_KEY) secrets.set('anthropic', envFile.ANTHROPIC_API_KEY);
  if (envFile.STRIPE_SECRET_KEY) secrets.set('stripe', envFile.STRIPE_SECRET_KEY);
  if (envFile.AWS_ACCESS_KEY_ID) secrets.set('aws', {
    accessKeyId: envFile.AWS_ACCESS_KEY_ID,
    secretAccessKey: envFile.AWS_SECRET_ACCESS_KEY,
  });

  // Return only non- canary secrets
  for (const [key, val] of secrets) {
    if (key.includes('CANARY') || key.includes('canary') || val.toString().includes('CANARY')) {
      secrets.delete(key);
    }
  }

  return secrets;
};

const secretsConfig = validateSecrets(process.env);

// Export with protection against console logging
module.exports = secretsConfig;
```

