// Map of expected secrets with their purposes
const expectedSecrets = {
  DATABASE_URL: 'PostgreSQL/MySQL database connection string',
  JWT_SECRET: 'JWT signing key for authentication (>= 32 characters)',
  AWS_ACCESS_KEY_ID: 'AWS access key (if applicable)',
  AWS_SECRET_ACCESS_KEY: 'AWS secret key (if applicable)',
  ANTHROPIC_API_KEY: 'Anthropic API key',
  STRIPE_SECRET_KEY: 'Stripe private key',
  LOGFIRE_TOKEN: 'Logfire token',
  CORS_ORIGIN: 'Allowed origins for CORS (comma-separated)',
  REDIS_URL: 'Redis connection URL (if applicable)',
  S3_BUCKET: 'S3 bucket name (if applicable)',
};

const checkEnv = () => {
  console.log('🔐 Validating environment configuration...\n');

  const envFile = process.env.NODE_ENV === 'production' 
    ? '.env.production' 
    : (process.env.NODE_ENV === 'test' ? '.env.test' : '.env.local');

  const envPath = path.join(__dirname, .., envFile);

  if (!fs.existsSync(envPath)) {
    console.error(`❌ Environment file not found: ${envFile}`);
    process.exit(1);
  }

  const envContent = fs.readFileSync(envPath, 'utf8');
  const secrets = {};

  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, value] = trimmed.split('=');
      if (key && value) {
        secrets[key] = value;
      }
    }
  }

  let hasError = false;
  let hasWarning = false;

  for (const [key, purpose] of Object.entries(expectedSecrets)) {
    if (!secrets[key]) {
      console.error(`❌ Missing: ${key} - ${purpose}`);
      hasError = true;
    } else if (process.env.NODE_ENV === 'development') {
      console.warn(`⚠️  Found: ${key} for ${purpose}`);

      if (key.includes('KEY') || key.includes('SECRET') || key === 'JWT_SECRET') {
        if (secrets[key].includes('canary') || secrets[key].length < 24) {
          console.warn(`⚠️  WARNING: ${key} appears to be development/test value`);
        }
      }
    }
  }

  // Check for suspicious patterns
  for (const [key, value] of Object.entries(secrets)) {
    if (value.includes('password:') || value.includes('SECRET:')) {
      console.warn(`⚠️  WARNING: ${key} contains default credentials`);
      hasWarning = true;
    }
    if (value.includes('sk-') && value.includes('canary')) {
      console.warn(`⚠️  WARNING: ${key} contains 'canary' prefix - suspicious`);
      hasWarning = true;
    }
  }

  if (hasError) {
    console.error('\n❌ Environment validation FAILED. Check required secrets.');
    process.exit(1);
  } else if (hasWarning) {
    console.warn('\n⚠️  Environment validation completed with warnings.');
    console.warn('   Review and audit all secrets in production.');
  } else {
    console.log('\n✅ Environment validation PASSED.');
  }
};

checkEnv();
```

