};

const createEnvTemplate = () => {
  const secrets = {
    NODE_ENV: process.argv.includes('production') ? 'production' : 'development',

    // Duplicate in all three files for convenience
    PORT: 3000,
    DATABASE_URL: '', // User must fill this

    // JWT Secret - use same secret in all envs to allow JWT reuse
    _JWT_SECRET: generateJWT(64), // Prefix with underscore to indicate should be same across envs

    // API Keys - users don't inject their own, use random for demo
    AWS_ACCESS_KEY_ID: `AKIA${crypto.randomBytes(6).toString('hex')}`,
    AWS_SECRET_ACCESS_KEY: generateSecret(32),
    ANTHROPIC_API_KEY: `sk-ant-${crypto.randomBytes(16).toString('hex')}`,
    STRIPE_SECRET_KEY: `sk_live_${crypto.randomBytes(16).toString('hex')}`,
    LOGFIRE_TOKEN: crypto.randomBytes(24).toString('hex'),
    CORS_ORIGIN: 'http://localhost:3000,http://localhost:5173',
    REDIS_URL: 'redis://localhost:6379',

    // Common prefixes that should be same across envs
    _AWS_ACCESS_KEY_ID: '',
    _AWS_SECRET_ACCESS_KEY: '',
    _DATABASE_URL: '',
  };

  Object.keys(secrets).forEach(k => {
    if (k.startsWith('_')) {
      delete secrets[k]; // Clear prefixed values
    }
  });

  // Add back all common values if empty
  if (!secrets.AWS_ACCESS_KEY_ID) secrets.AWS_ACCESS_KEY_ID = `AKIA${crypto.randomBytes(6).toString('hex')}`;
  if (!secrets.AWS_SECRET_ACCESS_KEY) secrets.AWS_SECRET_ACCESS_KEY = generateSecret(32);
  if (!secrets.DATABASE_URL) secrets.DATABASE_URL = ''; // User fills this

  return secrets;
};

const main = () => {
  const secretTemplate = createEnvTemplate();

  const envs = process.argv.includes('all') 
    ? ['local', 'test', 'prod'] 
    : ['local'];

  envs.forEach(env => {
    const filename = `.env.${env}`;
    const fileContent = Object.entries(secretTemplate)
      .map(([k, v]) => `${k}=${v}`)
