/**
 * @file safe-app.js
 * Security hardened Express application with input validation and security headers
 * OWASP Top 10 Vulnerabilities Addressed:
 * - A03:2021 Injection (via express-validator)
 * - A05:2021 Security Misconfiguration (via Helmet.js)
 * - A07:2021 Authentication (via input validation)
 * - A09:2021 Security Logging and Monitoring (via request ID tracking)
 */

const express = require('express');
const helmet = require('helmet');
const { body, validationResult, param } = require('express-validator');

const app = express();

// Apply security headers globally
app.use(helmet({
  contentSecurityPolicy: false,  // Disabled for development - enable for production with strict config
  crossOriginEmbedderPolicy: false
}));

// Custom security headers
app.use((req, res, next) => {
  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');
  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');
  // Encourage XSS protection in browsers
  res.setHeader('X-XSS-Protection', '1; mode=block');
  // Control referrer policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  // Require HTTPS in production
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});

/**
 * Input Validation Middleware
 * Validates all query parameters and request data
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// Health check endpoint with no validation required
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    api_version: '1.0.0'
  });
});

// Secure user listing endpoint with input validation
app.get('/users', validateRequest, [
  // Validate optional pagination parameters
  param('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer'),
  param('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
], (req, res) => {
  const page = parseInt(req.params.page) || 1;
  const limit = Math.min(parseInt(req.params.limit) || 10, 100);

  // Validate pagination values after middleware processing
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }

  // Safe to use validated parameters
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
    { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    { id: 4, name: 'Diana', email: 'diana@example.com' },
    { id: 5, name: 'Eve', email: 'eve@example.com' },
  ];

  const startIndex = (page - 1) * limit;
  const paginatedUsers = allUsers.slice(startIndex, startIndex + limit);

  res.json({
    users: paginatedUsers,
    pagination: {
      page,
      limit,
      total: allUsers.length,
      totalPages: Math.ceil(allUsers.length / limit)
    }
  });
});

// Secure user lookup by ID endpoint with strict validation
app.get('/users/:id', validateRequest, [
  param('id')
    .isInt({ min: 1, max: 1000000 })
    .withMessage('User ID must be a positive integer not exceeding 1,000,000')
    .trim()
    .escape()  // Prevents XSS
    .len({ max: 32 })
    .withMessage('User ID must not exceed 32 characters')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }

  // Parameter is safely escaped and validated
  const userId = parseInt(req.params.id);

  // Mock user data (normally query database)
  const users = {
    '1': { id: 1, name: 'Alice', email: 'alice@example.com' },
    '2': { id: 2, name: 'Bob', email: 'bob@example.com' },
  };

  const user = users[userId.toString()];
  if (!user) {
    return res.status(404).json({
      error: 'User not found'
    });
  }

  res.json({
    user,
    request_id: req.id  // Add request logging if requestId library is added
  });
});

